// Enabled feeds from config/news-sources.json (tests keep the two in sync).
const feeds = [
  {
    "name": "TechCrunch",
    "url": "https://techcrunch.com/feed/"
  },
  {
    "name": "Vox",
    "url": "https://www.vox.com/rss/index.xml"
  },
  {
    "name": "CNBC Technology",
    "url": "https://www.cnbc.com/id/19854910/device/rss/rss.html"
  },
  {
    "name": "The Verge",
    "url": "https://www.theverge.com/rss/index.xml"
  },
  {
    "name": "Wired",
    "url": "https://www.wired.com/feed/rss"
  },
  {
    "name": "MIT Technology Review",
    "url": "https://www.technologyreview.com/feed/"
  },
  {
    "name": "Ars Technica",
    "url": "https://feeds.arstechnica.com/arstechnica/index"
  }
];
return feeds.map((feed) => ({ json: feed }));

// Read an env variable with a default. n8n 2.x blocks $env unless
// N8N_BLOCK_ENV_ACCESS_IN_NODE=false; fall back to the default in that case.
const env = (name, fallback) => {
  try {
    const value = $env[name];
    return value === undefined || value === '' ? fallback : value;
  } catch (error) {
    return fallback;
  }
};
const INCLUDE = ["AI", "artificial intelligence", "machine learning", "startup", "innovation", "technology", "business", "entrepreneurship"];
const EXCLUDE = ["sponsored", "advertisement", "promoted"];
const minAgeHours = Number(env('MIN_ARTICLE_AGE_HOURS', 1));
const maxAgeHours = Number(env('MAX_ARTICLE_AGE_HOURS', 48));
const maxPosts = Number(env('MAX_POSTS_PER_RUN', 1));

// Whole-word, case-insensitive matching ("AI" must not match "said").
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordRe = (words) => new RegExp(`\\b(${words.map(escapeRe).join('|')})\\b`, 'i');
const includeRe = wordRe(INCLUDE);
const excludeRe = wordRe(EXCLUDE);

// Canonical link: drop tracking parameters and fragments so the same story is one key.
const canonical = (link) => {
  try {
    const url = new URL(link);
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) {
      if (/^(utm_|fbclid|gclid|mc_)/i.test(key)) url.searchParams.delete(key);
    }
    return url.toString();
  } catch (error) {
    return String(link).trim();
  }
};

const feedNames = {};
for (const feed of $('Feed List').all()) {
  try { feedNames[new URL(feed.json.url).hostname.replace(/^www\./, '')] = feed.json.name; } catch (e) {}
}
const sourceOf = (link) => {
  try {
    const host = new URL(link).hostname.replace(/^www\./, '');
    const match = Object.keys(feedNames).find((h) => host === h || host.endsWith('.' + h) || h.endsWith('.' + host));
    return match ? feedNames[match] : host;
  } catch (error) {
    return 'RSS';
  }
};

const posted = new Set($getWorkflowStaticData('global').postedLinks || []);
const seenThisRun = new Set();
const now = Date.now();
const candidates = [];
for (const item of $input.all()) {
  const a = item.json;
  if (a.error || !a.title || !a.link) continue; // failed feeds arrive as error items
  const link = canonical(a.link);
  if (posted.has(link) || seenThisRun.has(link)) continue;
  const published = new Date(a.isoDate || a.pubDate || 0).getTime();
  const ageHours = (now - published) / 36e5;
  if (!Number.isFinite(ageHours) || ageHours < minAgeHours || ageHours > maxAgeHours) continue;
  const text = `${a.title} ${a.contentSnippet || a.content || ''}`;
  if (excludeRe.test(text) || !includeRe.test(text)) continue;
  seenThisRun.add(link);
  candidates.push({
    title: String(a.title).trim(),
    link,
    description: String(a.contentSnippet || a.content || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000),
    publishedAt: new Date(published).toISOString(),
    source: sourceOf(link),
  });
}
candidates.sort((x, y) => y.publishedAt.localeCompare(x.publishedAt));
// Zero items ends the run: nothing new to post.
return candidates.slice(0, maxPosts).map((json) => ({ json }));

// Read an env variable with a default. n8n 2.x blocks $env unless
// N8N_BLOCK_ENV_ACCESS_IN_NODE=false; fall back to the default in that case.
const env = (name, fallback) => {
  try {
    const value = $env[name];
    return value === undefined || value === '' ? fallback : value;
  } catch (error) {
    return fallback;
  }
};
const charLimit = Number(env('LINKEDIN_CHAR_LIMIT', 3000));
const articles = $('Filter and Dedup').all();
const out = [];
$input.all().forEach((item, index) => {
  const article = articles[index]?.json;
  if (!article) return;
  let parsed;
  try {
    parsed = JSON.parse(item.json.choices?.[0]?.message?.content ?? '');
  } catch (error) {
    parsed = null;
  }
  const summary = typeof parsed?.summary === 'string' ? parsed.summary.trim() : '';
  if (!summary) {
    // Never publish a half-parsed model answer; skip and keep the article for the next run.
    console.log(`Skipping "${article.title}": model did not return a valid summary`);
    return;
  }
  const tags = String(parsed.hashtags || '')
    .split(/\s+/)
    .map((t) => t.replace(/[^#A-Za-z0-9]/g, ''))
    .filter((t) => /^#[A-Za-z0-9]+$/.test(t))
    .slice(0, 3)
    .join(' ') || '#News #Technology';
  const head = `${article.title}\n\n`;
  const tail = `\n\nSource: ${article.link}\n\n${tags}`;
  const room = charLimit - head.length - tail.length;
  const body = summary.length > room ? summary.slice(0, Math.max(0, room - 3)).trimEnd() + '...' : summary;
  const postText = head + body + tail;
  out.push({ json: { ...article, summary: body, hashtags: tags, postText, characterCount: postText.length } });
});
return out;

// DRY_RUN is on: nothing is published and nothing is marked as posted.
return $input.all().map((item) => ({
  json: { dryRun: true, title: item.json.title, link: item.json.link, characterCount: item.json.characterCount, postText: item.json.postText },
}));

// Runs once per published post, only after LinkedIn accepted it.
const MAX_REMEMBERED = 1000;
const data = $getWorkflowStaticData('global');
const article = $('Format LinkedIn Post').item.json;
const links = [...new Set([...(data.postedLinks || []), article.link])];
data.postedLinks = links.slice(-MAX_REMEMBERED);
const postId = $json.urn || $json.id || null;
data.recentPosts = [...(data.recentPosts || []), { title: article.title, link: article.link, postId, postedAt: new Date().toISOString() }].slice(-50);
return { json: { success: true, postId, title: article.title, link: article.link, characterCount: article.characterCount } };
